ruleToc.nextTocUrl:
class.pages cc.0@tag.a.-1@href<js>
var regstr = new RegExp("(thread\.\*\?page=)(\\d+)","g");
var sa=regstr.exec(String(result));
var baseurl = sa[1];
var count =Number( sa[2]);
var list=new Array(count-2);
for(var i=2;i<=count;i++){
    list[i-2]=(baseurl+i);
}
result = list;
</js>

class.end.0@href<js>
var regstr = new RegExp("(\/wvov-\\d+-)(\\d+)","g");
var sa=regstr.exec(String(result));
var baseurl = sa[1];
var count =Number( sa[2]);
var list=new Array(count-2);
for(var i=2;i<=count;i++){
    list[i-2]=(baseurl+i+".asp");
}
result = list;
</js>
